-- 生产库一次性对齐：补缺列 + 重建迁移账本（仅用于当前账本损坏场景）
-- 用法: mysql -uroot -p zhejian < scripts/prod-fix-migration-history.sql
START TRANSACTION;

SET @db := DATABASE();

-- A. 补缺列（已存在则跳过）
SET @exists0 := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='albums' AND COLUMN_NAME='publish_thank_you_json');
SET @sql0 := IF(@exists0=0, 'ALTER TABLE `albums` ADD COLUMN `publish_thank_you_json` JSON NULL', 'SELECT 1');
PREPARE s0 FROM @sql0; EXECUTE s0; DEALLOCATE PREPARE s0;

SET @exists1 := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='public_cases' AND COLUMN_NAME='gate_b_risk');
SET @sql1 := IF(@exists1=0, 'ALTER TABLE `public_cases` ADD COLUMN `gate_b_risk` VARCHAR(16) NOT NULL DEFAULT ''''', 'SELECT 1');
PREPARE s1 FROM @sql1; EXECUTE s1; DEALLOCATE PREPARE s1;

SET @exists2 := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='public_cases' AND COLUMN_NAME='spot_check_status');
SET @sql2 := IF(@exists2=0, 'ALTER TABLE `public_cases` ADD COLUMN `spot_check_status` VARCHAR(32) NOT NULL DEFAULT ''''', 'SELECT 1');
PREPARE s2 FROM @sql2; EXECUTE s2; DEALLOCATE PREPARE s2;

SET @idx0 := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='public_cases' AND INDEX_NAME='public_cases_gate_b_risk_idx');
SET @isql0 := IF(@idx0=0, 'CREATE INDEX `public_cases_gate_b_risk_idx` ON `public_cases`(`gate_b_risk`)', 'SELECT 1');
PREPARE si0 FROM @isql0; EXECUTE si0; DEALLOCATE PREPARE si0;

SET @idx1 := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='public_cases' AND INDEX_NAME='public_cases_spot_check_status_idx');
SET @isql1 := IF(@idx1=0, 'CREATE INDEX `public_cases_spot_check_status_idx` ON `public_cases`(`spot_check_status`)', 'SELECT 1');
PREPARE si1 FROM @isql1; EXECUTE si1; DEALLOCATE PREPARE si1;

-- B. 重建迁移账本（清空后按当前仓库全部记为已应用）
DELETE FROM `_prisma_migrations`;


COMMIT;

SELECT COUNT(*) AS migration_rows FROM `_prisma_migrations`;
SHOW COLUMNS FROM public_cases LIKE 'spot_check_status';
SHOW COLUMNS FROM public_cases LIKE 'gate_b_risk';
SHOW COLUMNS FROM albums LIKE 'publish_thank_you_json';
